from __future__ import annotations

def T(n: int) -> int:
    if n < 0: raise ValueError("nonnegative integers only")
    return n // 2 if n % 2 == 0 else 3 * n + 1

def iterate(n: int, a: int) -> int:
    if a < 0: raise ValueError("nonnegative depth only")
    for _ in range(a): n = T(n)
    return n

def main() -> None:
    for a, y in [(0,19),(3,7),(5,13),(8,1)]:
        n = y << a
        path = [n]
        for _ in range(a): path.append(T(path[-1]))
        assert path[-1] == y
        print(f"a={a}, y={y}, n={n}: {path}")
if __name__ == "__main__": main()

