def canonical_invert(a: int, y: int) -> int:
    """Return an exact depth-a Collatz preimage of y."""
    if a < 0 or y < 0:
        raise ValueError("a and y must be nonnegative")
    return y << a

from typing import Tuple

def persistent_collision(k: int, depth: int) -> Tuple[int, int]:
    """Return a collision for every requested positive depth."""
    if k < 0 or depth <= 0:
        raise ValueError("require k >= 0 and depth > 0")
    return 2 * k + 1, 12 * k + 8

from typing import List

def exact_trajectory(n: int, depth: int) -> List[int]:
    if n < 0 or depth < 0:
        raise ValueError("n and depth must be nonnegative")
    path = [n]
    for _ in range(depth):
        n = n // 2 if n % 2 == 0 else 3 * n + 1
        path.append(n)
    return path

